CREATE TABLE `perpetrator` (`Perpetrator_ID` DECIMAL(18,2), `People_ID` DECIMAL(18,2), `Date` VARCHAR(100), `Year` DECIMAL(18,2), `Location` VARCHAR(100), `Country` VARCHAR(100), `Killed` DECIMAL(18,2), `Injured` DECIMAL(18,2));
CREATE TABLE `people` (`People_ID` DECIMAL(18,2), `Name` VARCHAR(100), `Height` DECIMAL(18,2), `Weight` DECIMAL(18,2), `Home Town` VARCHAR(100));
